from pathlib import Path
from html import escape
root=Path(__file__).parent
EMAIL='inamullahbaryar@gmail.com' # Confirm this is your preferred public support contact before deployment.
NAME='PageFlow Agent'
navs=[('index.html','Home'),('services.html','Services'),('about.html','About'),('privacy-policy.html','Privacy Policy'),('terms.html','Terms'),('data-deletion.html','Data Deletion')]
def layout(filename,title,desc,content):
    nav=''.join(f'<a class="{"active" if file==filename else ""}" href="{file}">{label}</a>' for file,label in navs)
    footer=''.join(f'<a href="{file}">{label}</a>' for file,label in navs)
    markup=f'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(desc)}"><meta name="theme-color" content="#080e1e"><title>{escape(title)} | {NAME}</title><link rel="icon" type="image/svg+xml" href="assets/logo.svg"><link rel="stylesheet" href="assets/style.css"></head><body><header class="site-header"><div class="container nav-wrap"><a class="brand" href="index.html" aria-label="PageFlow Agent home"><span class="brand-mark">▶</span>{NAME}</a><button class="nav-toggle" aria-label="Toggle menu" aria-expanded="false">☰ Menu</button><nav class="nav-links" aria-label="Main navigation">{nav}</nav></div></header><main>{content}</main><footer class="site-footer"><div class="container"><div class="footer-grid"><div><a class="brand" href="index.html"><span class="brand-mark">▶</span>{NAME}</a><p>Independent video publishing automation for Facebook Pages you manage. Built with transparency, control, and privacy in mind.</p></div><div><div class="footer-title">Explore</div><div class="footer-links">{footer}</div></div><div><div class="footer-title">Contact</div><div class="footer-links"><a href="mailto:{EMAIL}">{EMAIL}</a><span>For support and data requests</span></div></div></div><div class="copyright"><span>© <span data-year>2026</span> {NAME}. All rights reserved.</span><span>Not affiliated with or endorsed by Meta or Facebook.</span></div></div></footer><script src="assets/site.js"></script></body></html>'''
    (root/filename).write_text(markup,encoding='utf-8')
def header(tag,title,sub):return f'<section class="page-header"><div class="container"><span class="eyebrow"><span class="dot"></span>{tag}</span><h1>{title}</h1><p>{sub}</p></div></section>'
def article(links,parts):
    aside=''.join(f'<a href="#{ident}">{label}</a>' for ident,label in links)
    return f'<div class="container article-wrap"><aside class="side-nav"><b>On this page</b>{aside}</aside><div class="article">{parts}</div></div>'
def part(ident,title,content):return f'<section id="{ident}"><h2>{title}</h2>{content}</section>'
email=f'<a class="contact-link" href="mailto:{EMAIL}">{EMAIL}</a>'
layout('index.html','Automate Your Facebook Page Videos','A professional informational website for PageFlow Agent, a Facebook Page video publishing automation application.', '''<section class="hero"><div class="container hero-grid"><div><span class="eyebrow"><span class="dot"></span>Smart content publishing</span><h1>Publish videos.<br><span class="gradient-text">On your schedule.</span></h1><p class="lead">PageFlow Agent helps authorized Page administrators organize and automatically publish their own video content to Facebook Pages, with clear control over every post.</p><div class="actions"><a class="btn" href="services.html">Explore our services →</a><a class="btn secondary" href="about.html">How it works</a></div><div class="fine">Designed for Page owners and authorized managers · Uses official Meta permissions where approved</div></div><div class="mock" role="img" aria-label="Illustration of a video publishing dashboard"><div class="mock-top"><div class="mock-head"><span class="mock-circle">▶</span> Video publishing workspace</div><span class="mock-pill">● Ready</span></div><div class="mock-main"><div class="preview"><span class="play">▶</span></div><div class="mock-filename">Your next video post</div><div class="mock-meta">Selected Facebook Page · Scheduled publishing</div><div class="mock-bottom"><span class="mock-status">● Publishing workflow</span><span class="mini-btn">Manage videos</span></div></div></div></div></section><section class="section alt"><div class="container"><div class="section-head"><span class="eyebrow">Why PageFlow</span><h2>All the essentials for simpler publishing</h2><p>A focused automation workflow to reduce repetitive tasks while keeping Page owners in charge.</p></div><div class="cards"><div class="feature"><span class="icon">↗</span><h3>Automated publishing</h3><p>Prepare a publishing workflow for approved, owned video content on your selected Facebook Page.</p></div><div class="feature"><span class="icon">▦</span><h3>Organized video queue</h3><p>Keep titles, descriptions, and planned uploads organized in one content pipeline.</p></div><div class="feature"><span class="icon">♢</span><h3>Privacy-first approach</h3><p>Access only the permissions required and provide simple ways to revoke access or request deletion.</p></div></div></div></section><section class="section"><div class="container"><div class="section-head"><span class="eyebrow">Process</span><h2>How the agent is designed to work</h2><p>A clear, permission-based process from Page connection to successful publishing.</p></div><div class="steps"><div class="step"><div class="step-number">01</div><h3>Authorize access</h3><p>A Page administrator securely authorizes relevant Page access through Meta's official authorization flow.</p></div><div class="step"><div class="step-number">02</div><h3>Prepare video content</h3><p>Provide your video, caption, and requested publishing settings. You stay responsible for the content.</p></div><div class="step"><div class="step-number">03</div><h3>Publish to your Page</h3><p>When configured and authorized, the agent submits video posts using applicable Meta APIs.</p></div></div></div></section><section class="section alt"><div class="container"><div class="cta"><div><h2>Transparency is part of the workflow.</h2><p>Review how we handle your information, permissions, and data deletion requests.</p></div><a class="btn" href="privacy-policy.html">Read privacy policy →</a></div></div></section>''')
layout('services.html','Services','Learn about video publishing, workflow organization, and access management.',header('What we do','Services for thoughtful <span class="gradient-text">video publishing</span>','Tools and workflows intended to support automated content publishing on Facebook Pages you own or are authorized to manage.')+'''<section class="section"><div class="container"><div class="detail-cards"><div class="feature"><span class="icon">▶</span><h3>Video publishing automation</h3><p>Submit video content for publication to an authorized Facebook Page through supported Meta publishing APIs, subject to permission availability and platform limits.</p></div><div class="feature"><span class="icon">◷</span><h3>Publishing schedules</h3><p>Structure content around planned posting times. Actual scheduling requires a configured server-side publishing service.</p></div><div class="feature"><span class="icon">▤</span><h3>Metadata preparation</h3><p>Organize captions, descriptions, and titles for your own videos before they are published.</p></div><div class="feature"><span class="icon">♙</span><h3>Account & access controls</h3><p>Support secure authorization, access revocation, and deletion requests for data handled by the agent.</p></div></div><div class="notice" style="margin-top:32px"><strong>Important:</strong> This public site explains the app and its policies. It is not an operational upload dashboard or a running Facebook automation backend. Connecting Facebook and publishing videos requires separate secure server-side implementation and appropriate Meta permissions.</div></div></section>''')
layout('about.html','About Us','Discover why PageFlow Agent was created and how it serves Facebook Page managers.',header('Our story','Built for Page owners, <span class="gradient-text">not complexity.</span>','PageFlow Agent is an independent application concept focused on helping authorized Facebook Page managers reduce repetitive video publishing tasks.')+'''<section class="section"><div class="container"><div class="detail-cards"><div class="feature"><span class="icon">◎</span><h3>Our mission</h3><p>Make Page video publishing more structured, reliable, and manageable while respecting creator control and platform requirements.</p></div><div class="feature"><span class="icon">✧</span><h3>Our approach</h3><p>Use official authorization flows, request only necessary permissions, and provide transparent policies for data handling and removal.</p></div></div><div class="article" style="max-width:800px;margin:55px auto 0"><h2>Independent and user-directed</h2><p>PageFlow Agent is not an official Meta or Facebook product. Only individuals who own a Page or have appropriate management rights should connect and publish to it. Content must comply with copyright law, Meta's policies, and applicable local requirements.</p><h2>Questions and feedback</h2><p>Reach our team at <a class="contact-link" href="mailto:inamullahbaryar@gmail.com">inamullahbaryar@gmail.com</a> for support, privacy questions, or data removal assistance.</p></div></div></section>''')
privacy=[('overview','Overview'),('data','Data we process'),('use','Why we use data'),('sharing','Sharing & storage'),('security','Security & retention'),('rights','Choices & deletion'),('changes','Policy updates'),('contact','Contact')]
privacybody=part('overview','1. Scope and overview','<p>Effective date: October 15, 2026. This policy explains how PageFlow Agent (“we,” “our,” or “the app”) handles information when an authorized user connects a Facebook Page or uses our video publishing workflow. This policy covers the app itself, not merely this informational website.</p>')+part('data','2. Information we may process','<p>Depending on the features enabled and permissions granted, we may process:</p><ul><li>Facebook account identifiers or basic profile details exposed by approved authorization.</li><li>Page identifiers, Page names, Page access tokens, and relevant Page management permissions.</li><li>Videos supplied for publishing, captions, titles, descriptions, scheduling choices, and upload status.</li><li>Operational records such as timestamps, publishing results, and technical error logs needed to provide or troubleshoot the service.</li><li>Communications you send to our support email.</li></ul><p>We do not ask you to share your Facebook password with us.</p>')+part('use','3. How we use information','<p>We process permitted information to identify Pages you are authorized to manage, authenticate authorized API actions, publish content you request, operate or troubleshoot an authorized workflow, address support requests, maintain app security, and fulfill deletion obligations. We do not use Facebook data for unrelated advertising or sell it.</p>')+part('sharing','4. Sharing and storage','<p>We may transmit the content and related Page information needed to fulfill an authorized publishing action to Meta through its APIs. If third-party infrastructure providers process data on our behalf, they must be used only to support the service and subject to appropriate security and contractual controls. We do not publish your content to a Page without an authorized workflow.</p><p>Exact hosting providers, storage locations, and data subprocessors must be confirmed and reflected here before any real user data is processed.</p>')+part('security','5. Security and retention','<p>Access tokens should be stored securely, never included in publicly accessible code, and available only to authorized services. We aim to retain data only as long as needed to deliver the service, resolve issues, or meet lawful requirements. Final retention periods must reflect the actual backend implementation.</p>')+part('rights','6. Your choices and deletion',f'<p>You can revoke Facebook access through your Facebook settings. You can also request deletion of personal information processed by PageFlow Agent by emailing {email}, or following the steps on our <a class="contact-link" href="data-deletion.html">Data Deletion page</a>. We will review and process legitimate requests without undue delay, subject to applicable legal requirements.</p>')+part('changes','7. Changes to this policy','<p>We may revise this policy to reflect changes in features, processing activities, legal obligations, or Meta requirements. The effective date will be updated when revisions are published.</p>')+part('contact','8. Contact',f'<p>For questions about privacy, permissions, or personal data: {email}.</p><div class="notice"><strong>Before app submission:</strong> Verify that each data category, storage practice, retention statement, and contact detail matches the real app and backend. Publishing this template does not itself guarantee Meta approval.</div>')
layout('privacy-policy.html','Privacy Policy','Privacy policy for Facebook Page video publishing automation.',header('Legal & trust','Privacy Policy','How PageFlow Agent processes information associated with authorized Facebook Page publishing.')+article(privacy,privacybody))
terms=[('acceptance','Acceptance'),('eligibility','Authorized use'),('content','Your content'),('platform','Platform requirements'),('availability','Service availability'),('liability','Responsibility'),('termination','Termination'),('updates','Changes'),('contact','Contact')]
termsbody=part('acceptance','1. Acceptance of terms','<p>Effective date: October 15, 2026. These Terms of Service govern use of PageFlow Agent and its associated Facebook Page video publishing workflows. By using the service, you agree to these terms and our Privacy Policy.</p>')+part('eligibility','2. Eligibility and authorized use','<p>You may connect and post only to Facebook Pages you own or are explicitly authorized to manage. You must comply with applicable law and the policies, permissions, and developer requirements established by Meta.</p>')+part('content','3. Content ownership and permissions','<p>You retain responsibility for the videos, captions, and other material you submit. You represent that you hold the necessary rights to publish the content and that it does not infringe others’ intellectual property, privacy, or other rights. We do not claim ownership of your submitted videos.</p>')+part('platform','4. Facebook and third-party platforms','<p>PageFlow Agent is independent of Meta and Facebook. API features, rate limits, access permissions, publication behavior, and account status are controlled by Meta and may change. Use of Facebook is governed by Meta’s separate terms and policies.</p>')+part('availability','5. Availability and changes','<p>The service may be modified, paused, or discontinued. We cannot guarantee uninterrupted operation, specific publication times, successful post delivery, or approval of any API permission request.</p>')+part('liability','6. Your responsibilities','<p>You are responsible for lawful use, Page access, accuracy of settings, and verifying publication results. To the extent permitted by applicable law, the service is offered without guarantees of uninterrupted performance or fitness for a particular purpose. Nothing here excludes liability that cannot legally be excluded.</p>')+part('termination','7. Ending access','<p>You may stop using the service, remove its Facebook integration, and request deletion of applicable data. We may restrict access for misuse, unauthorized publishing, security concerns, or violations of these terms.</p>')+part('updates','8. Updates to these terms','<p>We may revise these terms to reflect service or legal changes. The posted effective date indicates the current version.</p>')+part('contact','9. Contact',f'<p>Questions about these terms can be sent to {email}.</p>')
layout('terms.html','Terms of Service','Terms governing the use of PageFlow Agent.',header('Legal & trust','Terms of Service','Understand your rights and responsibilities when using PageFlow Agent.')+article(terms,termsbody))
deletelinks=[('request','Request deletion'),('facebook','Remove access on Facebook'),('scope','What deletion includes'),('after','What happens next'),('help','Contact')]
deletebody=part('request','1. Submit a data deletion request',f'<p>You may ask us to delete Facebook-related personal data processed or stored by PageFlow Agent. To submit a request:</p><ol class="deletion-steps"><li>Send an email to {email} with the subject <strong>PageFlow Agent — Data Deletion Request</strong>.</li><li>Include the Facebook Page name or Page ID associated with the app and a contact email so we can locate your records. <strong>Do not send your Facebook password or access token.</strong></li><li>We may ask for reasonable verification to ensure the requester is authorized before removing associated records.</li></ol><p><a class="btn" href="mailto:{EMAIL}?subject=PageFlow%20Agent%20-%20Data%20Deletion%20Request">Email deletion request →</a></p>')+part('facebook','2. Remove access on Facebook','<p>You can also revoke the integration from your Facebook account’s settings under Business Integrations (or the equivalent app connection settings currently shown by Meta). Find PageFlow Agent and remove its permissions. Revoking access prevents future authorized API actions; it does not necessarily delete copies of records previously stored by this app, so email us if deletion is needed.</p>')+part('scope','3. Data covered by the request','<p>Depending on what has actually been stored, deletion may include Facebook user and Page identifiers, access tokens, saved upload metadata, queued content, uploaded temporary files, and operational records linked to your account. Data retained only where legally necessary is handled according to applicable law. Content already published to Facebook may need to be removed separately from the Page through Facebook tools.</p>')+part('after','4. After we receive your request','<p>We will review the request, verify authorization if needed, and process eligible deletion without undue delay. We will reply to your email with the outcome or any additional details needed to complete the request. This page provides instructions, not an automatic deletion callback API.</p>')+part('help','5. Need assistance?',f'<p>For questions about deletion, access revocation, or privacy, email {email}. See our <a class="contact-link" href="privacy-policy.html">Privacy Policy</a> for more information.</p><div class="notice"><strong>Meta developer configuration:</strong> Use the public URL of this page as a <em>Data Deletion Instructions URL</em> if your app setup offers that option. A separate Data Deletion Callback URL requires an actual secure server endpoint, which is not included in this static site.</div>')
layout('data-deletion.html','Data Deletion','How to request deletion of Facebook data associated with PageFlow Agent.',header('Your privacy choices','User Data Deletion','Clear instructions for revoking application access and requesting removal of data processed by PageFlow Agent.')+article(deletelinks,deletebody))
print('Generated six pages.')
